import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';
import ProgressBar from '../components/ProgressBar';

export default function RoadmapPage() {
  const { name } = useParams();
  const navigate = useNavigate();
  const [roadmapPlan, setRoadmapPlan] = useState([]);
  const [domain, setDomain] = useState('');
  const [timeline, setTimeline] = useState('');

  useEffect(() => {
    const raw = localStorage.getItem('roadmapPlan');
    setRoadmapPlan(raw ? JSON.parse(raw) : []);
    setDomain(localStorage.getItem('selectedDomain') || name || 'General');
    setTimeline(localStorage.getItem('timeline') || '3 months');
  }, [name]);

  const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
  const totalTasks = roadmapPlan.flat().length;
  const totalDays = Math.ceil(totalTasks / 4);
  const completionPercentage = totalDays > 0 ? Math.round((completedDays.length / totalDays) * 100) : 0;

  const getPhaseProgress = (idx, tasks) => {
    let tasksBefore = 0;
    for (let i = 0; i < idx; i++) tasksBefore += roadmapPlan[i].length;
    const startDay = Math.floor(tasksBefore / 4) + 1;
    const duration = Math.ceil(tasks.length / 4);
    const completed = completedDays.filter(d => d >= startDay && d < startDay + duration).length;
    return Math.min(100, Math.round((completed / duration) * 100));
  };

  return (
    <div className="space-y-8 pb-20">
      <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-700 dark:from-slate-800 dark:to-slate-900">
        <h1 className="text-4xl font-bold text-slate-900 dark:text-white uppercase tracking-tight">{domain.replace(/-/g, ' ')} Roadmap</h1>
        <p className="mt-2 text-slate-600 dark:text-slate-400 font-medium">Concept-Driven Syllabus for {timeline}</p>
        
        <div className="mt-8 flex flex-col gap-6 lg:flex-row">
          <div className="flex-1 bg-white/50 p-6 rounded-3xl border border-white/50 backdrop-blur-md">
            <p className="text-sm font-bold text-slate-500 uppercase mb-2">Curriculum Completion</p>
            <ProgressBar label="Overall" value={completionPercentage} />
          </div>
          <div className="bg-teal-50 p-6 rounded-3xl border border-teal-100 flex items-center justify-center min-w-[200px]">
            <div className="text-center">
              <p className="text-xs font-bold text-teal-600 uppercase">Duration</p>
              <p className="text-2xl font-black text-teal-900">{timeline}</p>
            </div>
          </div>
        </div>
      </div>

      <div className="space-y-6">
        <h2 className="text-2xl font-bold flex items-center gap-3">📚 Learning Phases <span className="text-sm font-normal text-slate-500">({roadmapPlan.length} weeks)</span></h2>
        
        {roadmapPlan.map((phase, idx) => (
          <div key={idx} className="bg-white rounded-[2rem] border border-slate-200 p-8 shadow-sm hover:shadow-md transition-shadow">
            <div className="flex items-start justify-between mb-6">
              <div className="flex items-center gap-4">
                <span className="h-12 w-12 rounded-2xl bg-teal-500 flex items-center justify-center text-white text-xl font-bold shadow-teal-200 shadow-lg">{idx + 1}</span>
                <div>
                  <h3 className="text-xl font-bold">Phase {idx + 1}: Deep Concept Mastery</h3>
                  <p className="text-sm text-slate-500">{phase.length} curated technical tasks</p>
                </div>
              </div>
              <div className="w-48 text-right">
                <p className="text-xs font-bold text-slate-400 mb-1">PHASE PROGRESS</p>
                <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div className="h-full bg-teal-500" style={{width: `${getPhaseProgress(idx, phase)}%`}}></div>
                </div>
              </div>
            </div>

            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {phase.map((task, tIdx) => (
                <div key={tIdx} className="p-4 rounded-2xl bg-slate-50 border border-slate-100 text-sm text-slate-700 flex gap-3 items-start">
                  <span className="text-teal-500 font-bold">✓</span>
                  {task}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="fixed bottom-8 left-1/2 -translate-x-1/2 z-50">
        <Button onClick={() => navigate('/tasks')} className="px-12 py-5 text-xl shadow-2xl rounded-full scale-105">Start Learning Journey 🚀</Button>
      </div>
    </div>
  );
}
